from __future__ import annotations
from typing import Sequence

def values(p: Sequence[float], good: float, bad: float) -> list[float]:
    return [bad + (good - bad) * x for x in p]

def regret_report(p: Sequence[float], good: float, bad: float, a: int, b: int) -> None:
    v = values(p, good, bad)
    epsilon = max(0.0, p[a] - p[b])
    print({"actual_regret": v[a] - v[b], "upper_bound": (good - bad) * epsilon})

if __name__ == "__main__":
    regret_report([.58, .33, .09], .95, .15, 0, 1)

from __future__ import annotations

def spin(p: float) -> float:
    return 2.0 * p - 1.0

def magnetization(rows: int, columns: int, p: float) -> float:
    return rows * columns * spin(p)

if __name__ == "__main__":
    p = .7
    print("score and complement:", spin(p), spin(1-p))
    print("magnetization and flip:", magnetization(4, 5, p), magnetization(4, 5, 1-p))

