from __future__ import annotations
from typing import Sequence

def compare_rankings(posterior: Sequence[float], hit_rewards: Sequence[float]) -> dict[str, object]:
    if len(posterior) != len(hit_rewards) or not posterior:
        raise ValueError("equal nonempty inputs required")
    expected = [p * r for p, r in zip(posterior, hit_rewards)]
    map_choice = max(range(len(posterior)), key=posterior.__getitem__)
    utility_choice = max(range(len(expected)), key=expected.__getitem__)
    return {"map_choice": map_choice, "utility_choice": utility_choice,
            "disagree": map_choice != utility_choice, "expected_values": expected}

